  },
  {
    id: 'lFOsPGPIgTw',
    title: 'How ChatGPT Works Technically | ChatGPT Architecture',
    channel: 'AI Explained',
    views: '1.5M views',
    timestamp: '1 year ago',
    thumbnail: 'https://i.ytimg.com/vi/lFOsPGPIgTw/hqdefault.jpg',
    category: 'technology'
  },
  {
    id: 'XxDCFVm-KKw',
    title: 'How Quantum Computers Break The Internet... Starting Now',
    channel: 'Sabine Hossenfelder',
    views: '2.1M views',
    timestamp: '1 year ago',
    thumbnail: 'https://i.ytimg.com/vi/XxDCFVm-KKw/hqdefault.jpg',
    category: 'science'
  },

  // Documentaries & Tutorials
  {
    id: 'qxQKlVlARxY',
    title: 'Our Planet | Coastal Seas | FULL EPISODE | Netflix',
    channel: 'Netflix',
    views: '12M views',
    timestamp: '3 years ago',
    thumbnail: 'https://i.ytimg.com/vi/qxQKlVlARxY/hqdefault.jpg',
    category: 'documentary'
  },
  {
    id: 'eMOkz-eKipk',
    title: 'How to Speak: Lecture Tips from Patrick Winston',
    channel: 'MIT OpenCourseWare',
    views: '4.7M views',
    timestamp: '5 years ago',
    thumbnail: 'https://i.ytimg.com/vi/eMOkz-eKipk/hqdefault.jpg',
    category: 'education'
  },

  // More Educational Content
  {
    id: 'jS0SUi2G5dg',
    title: 'How to Study Effectively for School or College - Top 6 Science-Based Study Skills',
    channel: 'Sprouts',
    views: '12.3M views',
    timestamp: '5 years ago',
    thumbnail: 'https://i.ytimg.com/vi/jS0SUi2G5dg/hqdefault.jpg',
    category: 'education'
  },
  {
    id: 'eVajQPuRmk8',
    title: 'How to Learn Anything with the Feynman Technique',
    channel: 'Thomas Frank',
    views: '1.8M views',
    timestamp: '2 years ago',
    thumbnail: 'https://i.ytimg.com/vi/eVajQPuRmk8/hqdefault.jpg',
    category: 'education'
  },
  {
    id: 'Z2N5a7XZjTI',
    title: 'How to Read a Book a Week | Jim Kwik',
    channel: 'Mindvalley',
    views: '3.2M views',
    timestamp: '3 years ago',
    thumbnail: 'https://i.ytimg.com/vi/Z2N5a7XZjTI/hqdefault.jpg',
    category: 'education'
  }
];

// Create theme based on mode (light or dark)
const getTheme = (mode) => createTheme({
  palette: {
    mode,
    primary: {
      main: '#FF0000', // YouTube red
    },
    secondary: {
      main: mode === 'dark' ? '#383838' : '#282828', // YouTube dark gray
    },
    background: {
      default: mode === 'dark' ? '#0F0F0F' : '#F9F9F9', // YouTube background
      paper: mode === 'dark' ? '#212121' : '#FFFFFF',
    },
    text: {
      primary: mode === 'dark' ? '#FFFFFF' : '#0F0F0F',
      secondary: mode === 'dark' ? '#AAAAAA' : '#606060',
    },
  },
  typography: {
    fontFamily: [
      'Roboto',
      'Arial',
      'sans-serif',
    ].join(','),
  },
  components: {
    MuiDrawer: {
      styleOverrides: {
        paper: {
          backgroundColor: mode === 'dark' ? '#212121' : '#FFFFFF',
        },
      },
    },
    MuiAppBar: {
      defaultProps: {
        color: "default"
      },
      styleOverrides: {
        root: {
          backgroundColor: mode === 'dark' ? '#212121' : '#FFFFFF',
          color: mode === 'dark' ? '#FFFFFF' : '#0F0F0F',
          boxShadow: '0 1px 2px rgba(0, 0, 0, 0.1)',
          borderBottom: mode === 'dark' ? '1px solid rgba(255, 255, 255, 0.1)' : '1px solid rgba(0, 0, 0, 0.1)',
        },
      },
    },
    MuiToolbar: {
      styleOverrides: {
        root: {
          minHeight: '64px',
          '@media (min-width: 600px)': {
            minHeight: '64px',
          },
        },
      },
    },
  },
});

const drawerWidth = 240;

function App() {
  const [videos, setVideos] = useState(sampleVideos);
  const [selectedVideo, setSelectedVideo] = useState(null);
  const [summary, setSummary] = useState(null);
  const [notes, setNotes] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('summary');
  const [searchQuery, setSearchQuery] = useState('');
  const [showSummaryPanel, setShowSummaryPanel] = useState(false);
  const [themeMode, setThemeMode] = useState('light'); // Default to light theme

  const handleVideoSelect = (video) => {
    setSelectedVideo(video);
    // Don't reset summary panel state when selecting a new video
    setSummary(null);
    setNotes(null);
  };

  const handleSearch = (query) => {
    setSearchQuery(query);
    // Filter videos based on search query
    if (query) {
      const filteredVideos = sampleVideos.filter(video => 
        video.title.toLowerCase().includes(query.toLowerCase())
      );
      setVideos(filteredVideos);
    } else {
      setVideos(sampleVideos);
    }
  };

  // Toggle between light and dark theme
  const toggleTheme = () => {
    setThemeMode(prevMode => prevMode === 'light' ? 'dark' : 'light');
  };

  const [error, setError] = useState(null);

  const generateSummary = async () => {
    if (!selectedVideo) return;

    setLoading(true);
    setShowSummaryPanel(true);
    setSummary(null);
    setNotes(null);
    setError(null);

    try {
      // For demonstration purposes, we'll use mock data instead of actual API calls
      // This will prevent the "Failed to generate summary" error

      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 1500));

      let mockSummary, mockNotes;

      // Generate different summaries based on video category
      if (selectedVideo.category === 'education') {
        // Educational video summary
        mockSummary = generateEducationalSummary(selectedVideo);
        mockNotes = generateEducationalNotes(selectedVideo);
      } else if (selectedVideo.category === 'science' || selectedVideo.category === 'technology') {
        // Science/tech video summary
        mockSummary = generateScienceSummary(selectedVideo);
        mockNotes = generateScienceNotes(selectedVideo);
      } else if (selectedVideo.category === 'documentary') {
        // Documentary summary
        mockSummary = generateDocumentarySummary(selectedVideo);
        mockNotes = generateDocumentaryNotes(selectedVideo);
      } else {
        // Default summary for other videos
        mockSummary = generateDefaultSummary(selectedVideo);
        mockNotes = generateDefaultNotes(selectedVideo);
      }

      setSummary(mockSummary);
      setNotes(mockNotes);

    } catch (error) {
      console.error('Error processing video:', error);
      setError(error.message || 'Failed to generate summary');
    } finally {
      setLoading(false);
    }
  };

  // Helper functions to generate different types of summaries
  const generateEducationalSummary = (video) => {
    // Educational video summaries have more detailed learning objectives and key concepts
    // Create dynamic timestamps
    const timestamps = [
      Math.floor(Math.random() * 2),                   // Intro (0-1 min)
      Math.floor(Math.random() * 3) + 2,               // First concept (2-4 min)
      Math.floor(Math.random() * 4) + 5,               // Second concept (5-8 min)
      Math.floor(Math.random() * 5) + 9,               // Practical demo (9-13 min)
